dataset.reference_raw_json:
{
  "parts": [
    {
      "text": "The container in pod payment-worker-v1 (Incident ID INC-2026-0926-PAY) was terminated by the Linux kernel OOM killer with exit code 137 after reaching its 512MiB memory cgroup limit due to an unbounded batch fetch size (SETTLEMENT_BATCH_SIZE=50000) in BatchSettlementProcessor loading 480MB into JVM heap and triggering java.lang.OutOfMemoryError: Java heap space. Applied remediation capped SETTLEMENT_BATCH_SIZE=1000, added JVM flag -XX:MaxRAMPercentage=75.0, and raised the memory limit from 512MiB to 1024MiB."
    }
  ],
  "role": "model"
}

